effect.shader:
    
    // Hash function
    float hash(vec2 p) {
        vec3 p3  = fract(vec3(p.xyx) * .1031);
        p3 += dot(p3, p3.yzx + 33.33);
        return fract((p3.x + p3.y) * p3.z);
    }
    
    mat2 rot2(float a){ float s = sin(a), c = cos(a); return mat2(c,-s,s,c); }
    
    // 3D Rotations
    mat3 rotX(float a) { float c=cos(a), s=sin(a); return mat3(1,0,0, 0,c,-s, 0,s,c); }
    mat3 rotY(float a) { float c=cos(a), s=sin(a); return mat3(c,0,s, 0,1,0, -s,0,c); }
    mat3 rotZ(float a) { float c=cos(a), s=sin(a); return mat3(c,-s,0, s,c,0, 0,0,1); }
    
    mat3 transpose3(mat3 m) {
        return mat3(
            m[0][0], m[1][0], m[2][0],
            m[0][1], m[1][1], m[2][1],
            m[0][2], m[1][2], m[2][2]
        );
    }
    
    mat3 getRot3D(vec3 r) {
        vec3 rad = radians(r);
        return rotY(rad.y) * rotX(rad.x) * rotZ(rad.z);
    }

    // Ray intersections
    float iSphere(vec3 ro, vec3 rd, float r) {
        float b = dot(ro, rd);
        float c = dot(ro, ro) - r*r;
        float h = b*b - c;
        if(h < 0.0) return -1.0;
        return -b - sqrt(h);
    }

    vec2 iBox(vec3 ro, vec3 rd, vec3 boxSize, out vec3 outNormal) {
        vec3 m = 1.0 / rd;
        vec3 n = m * ro;
        vec3 k = abs(m) * boxSize;
        vec3 t1 = -n - k;
        vec3 t2 = -n + k;
        float tN = max(max(t1.x, t1.y), t1.z);
        float tF = min(min(t2.x, t2.y), t2.z);
        if(tN > tF || tF < 0.0) return vec2(-1.0);
        outNormal = -sign(rd) * step(t1.yzx, t1.xyz) * step(t1.zxy, t1.xyz);
        return vec2(tN, tF);
    }

    // Physics parameters for a piece
    struct Shard {
        vec2 disp;
        float rot;
        vec2 pivot;
        float depth;
        float scale;
        mat3 rot3d; // Rotation for the piece itself
        vec2 uvOffset; // Jitter for sampling
    };
    
    // Generate shard physics
    // cid: Cell ID
    // k: Sub-piece index (0 or 1)
    Shard getShard(vec2 cid, int k, float t, float g) {
        Shard S;
        
        vec2 cellCenter = (cid + 0.5) * g;
        
        // Random seed unique to this piece
        float rnd = hash(cid + vec2(float(k)*1.23, float(seed)));
        S.uvOffset = vec2(hash(cid + rnd), hash(cid - rnd)) - 0.5; // Jitter for sampling
        
        // Pivot point
        S.pivot = cellCenter / acScreenSize; // UV space pivot
        
        // Explosion Direction
        vec2 centerPx = origin * acScreenSize;
        vec2 dir = cellCenter - centerPx;
        float d = length(dir);
        vec2 normDir = dir / max(d, 1.0);
        
        // Randomize direction
        float angleVar = (rnd - 0.5) * randomness * 2.0; 
        normDir = rot2(angleVar) * normDir;
        
        // Force calculation
        float forceMag = strength * 500.0 * (1.0 + (rnd - 0.5) * randomness);
        
        vec2 vel = normDir * forceMag;
        vec2 grav = vec2(0.0, -gravity * 1000.0);
        
        // Physics equation
        float time = t * 2.0;
        
        S.disp = (vel * time + 0.5 * grav * time * time) / acScreenSize; // Convert px displacement to UV
        
        // Rotation
        S.rot = radians(rotation) * time * (rnd - 0.5) * 2.0;
        
        // Depth/Scale (2D fallback and 3D Z-displacement)
        float bZ = (style == 5) ? -3.0 : 1.0; // Window breaks forward (negative Z)
        S.depth = time * (rnd + 0.5) * bZ;
        S.scale = 1.0 / (1.0 + max(S.depth, -0.9) * 0.5);
        
        // 3D Scene Rotation + Shard Rotation
        vec3 worldRot = vec3(0.0, 0.0, degrees(S.rot)) + sceneRotation;
        S.rot3d = getRot3D(worldRot);
        
        return S;
    }
    
    // Inverse check
    // Returns color if uv0 maps to this piece
    vec4 checkPiece(vec2 cidC, int k, float t, float g, vec2 uvNow, out bool found, out float dOut) {
        Shard S = getShard(cidC, k, t, g);
        float aspect = acScreenSize.x / acScreenSize.y;
        
        if (style <= 1 || style == 5) {
            // 2D Logic (Blocks, Glass, or Window)
            vec2 uv0 = uvNow - S.disp;
            vec2 pRel = uv0 - S.pivot;
            pRel.x *= aspect;
            pRel /= S.scale;
            pRel = rot2(-S.rot) * pRel;
            pRel.x /= aspect;
            uv0 = pRel + S.pivot;
            
            vec2 px0 = uv0 * acScreenSize;
            vec2 cid0 = floor(px0 / g);
            vec2 q = fract(px0 / g);
            
            bool matchCell = length(cid0 - cidC) < 0.1;
            // Shard shape: style 1 and 5 use triangle split (Glass)
            bool isGlass = (style == 1 || style == 5);
            bool insideShape = (!isGlass) ? true : ((k == 0) ? (q.x + q.y < 1.0) : (q.x + q.y >= 1.0));
            
            found = matchCell && insideShape;
            if (found) {
                vec4 col = texture2DCv(inputImg.texture, clamp(uv0, 0.0, 1.0));
                if (col.a < 0.01) { found = false; return vec4(0.0); }
                dOut = S.depth;
                return col;
            }
            return vec4(0.0);
        } else {
            // 3D Logic
            // Ray setup
            // Camera at Z = -1.0, looking at Z = 0.0
            // Shards are centered at Z = 0 + S.depth
            vec3 ro = vec3((uvNow - S.pivot), -1.0);
            ro.x *= aspect;
            ro.xy -= S.disp * vec2(aspect, 1.0);
            ro.z -= S.depth; // Shift ray origin relative to relocated shard
            
            vec3 rd = normalize(vec3(0.0, 0.0, 1.0)); // Orthographic or weak perspective?
            // Let's do simple orthographic ray for "flat" logic but with 3D volume
            // Transform ro/rd into shard local space
            mat3 invRot = transpose3(S.rot3d);
            vec3 roL = invRot * ro;
            vec3 rdL = invRot * rd;
            
            float dHit = -1.0;
            vec3 normal = vec3(0.0, 0.0, -1.0);
            float shardSize = (g / acScreenSize.y) * 0.5; // Half size in relative units
            
            if (style == 2 || style == 4) {
                // Cube or Thick Glass
                float zThick = (style == 4) ? shardSize * 0.2 : shardSize;
                vec3 bSize = (style == 4) ? vec3(shardSize, shardSize, zThick) : vec3(shardSize);
                vec2 res = iBox(roL, rdL, bSize, normal);
                if (res.x > 0.0) dHit = res.x;
            } else if (style == 3) {
                // Sphere
                dHit = iSphere(roL, rdL, shardSize);
                normal = normalize(roL + rdL * dHit);
            }
            
            if (dHit > 0.0) {
                vec3 pHit = roL + rdL * dHit;
                vec3 worldNormal = S.rot3d * normal;
                
                // Texture sampling UV (Projected from front face)
                vec2 uv0 = (pHit.xy / (shardSize * 2.0)) + 0.5;
                
                // Add jitter/offset from shard origin
                vec2 sampleUV = S.pivot + (uv0 - 0.5) * (g / acScreenSize);
                
                vec4 col = texture2DCv(inputImg.texture, clamp(sampleUV, 0.0, 1.0));
                if (col.a < 0.01) { found = false; return vec4(0.0); }
                
                // Lighting
                vec3 lightDir = normalize(vec3(0.5, 0.5, -1.0));
                float diff = max(dot(worldNormal, lightDir), 0.0);
                float ambient = 0.4;
                col.rgb *= (ambient + (1.0 - ambient) * diff);
                
                found = true;
                dOut = S.depth + dHit * 0.1; // Return local depth
                return col;
            }
        }
        
        found = false;
        return vec4(0.0);
    }

    void main() {
        if (progress <= 0.001) {
             gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm);
             return;
        }
    
        vec2 uv = acScreenNorm;
        float g = max(grid, 5.0);
        
        vec2 px = uv * acScreenSize;
        vec2 baseCid = floor(px / g);
        
        float t = progress; 
        
        // Search Radius
        // As pieces fly further, we need to search wider.
        // Adaptive: proportional to strength * t
        // Cap it reasonable to preserve perf.
        int R = int(min(2.0 + strength * t * 20.0, 10.0));
        
        vec4 bestCol = vec4(0.0);
        float minDepth = 10000.0;
        bool hit = false;
        
        // Store winner parameters to re-sample with correct alpha
        vec2 winnerCid = vec2(0.0);
        int winnerK = 0;
        
        // Sub-piece count
        int kMax = (style == 1 || style == 5) ? 2 : 1; 

        for (int y = -R; y <= R; y++) {
            for (int x = -R; x <= R; x++) {
                 vec2 cidC = baseCid + vec2(float(x), float(y));
                 
                 for (int k = 0; k < kMax; k++) {
                     bool found;
                     float dHit;
                     vec4 res = checkPiece(cidC, k, t, g, uv, found, dHit);
                     if (found) {
                         if (dHit < minDepth) {
                             minDepth = dHit;
                             hit = true;
                             bestCol = res;
                         }
                     }
                 }
            }
        }
        
        if (hit) {
            gl_FragColor = bestCol;
        } else {
            gl_FragColor = vec4(0.0);
        }
    }
